const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-116.8672, 36.4619]); // Furnace Creek Visitor Center
  const date = '2013-06-30';

  // 2. Data Acquisition - ERA5-Land for air temperature
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(point)
    .select(['temperature_2m', 'dewpoint_temperature_2m']); // Includes 2m air temperature in Kelvin

  // Check collection size
  const size = era5.size().getInfo();
  console.log(`${date} Images: ${size}`);

  if (size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get daily maximum temperature
  const tempImg = era5.first();

  // Convert Kelvin to Celsius (ERA5 provides temperature in K)
  const tempC = tempImg.select('temperature_2m').subtract(273.15).rename('temp_c');

  // 4. Calculation - Extract temperature at point
  const stats = tempC.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const tempValue = stats.temp_c;

  // 5. Validation & Final Answer
  console.log(`Temperature: ${tempValue.toFixed(1)}°C`);

  // Check for invalid values
  if (tempValue === null || tempValue === undefined || isNaN(tempValue)) {
    console.log("<answer>C3</answer>");
  } else if (tempValue < -100 || tempValue > 100) { // Unrealistic temperature range
    console.log("<answer>C3</answer>");
  } else if (tempValue > 50) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
